def rr(start, end):
    return list(range(start, end + 1))


def spec(key, title, milestone, reqs, labels, objective, work, tests, outputs, deps=None):
    return {
        "key": key,
        "title": title,
        "milestone": milestone,
        "reqs": reqs,
        "labels": labels,
        "objective": objective,
        "work": work,
        "tests": tests,
        "outputs": outputs,
        "deps": deps or [],
    }


